using System;
using UnityEngine;

namespace MarrowRoad
{
    /// <summary>
    /// Data model for Assets/Game/Data/graybox_layout.json (generated by gen_layout.py).
    /// Units are metres. The enemy valley is -Z, the wall face sits at z = 0, +Y is up.
    /// </summary>
    [Serializable]
    public sealed class GrayboxLayout
    {
        public float wallTop = 20f;
        public LayoutBox[] boxes = Array.Empty<LayoutBox>();
        public LayoutParapet[] parapets = Array.Empty<LayoutParapet>();
        public LayoutParapet[] rails = Array.Empty<LayoutParapet>();
        public LayoutSpawn playerSpawn = new LayoutSpawn();
        public float[] gateCenter = { 140f, 13.5f, 0f };
        public float[] gateTarget = { 140f, 10f, -2f };
        public float[] spawnMin = { 90f, 0f, -230f };
        public float[] spawnMax = { 200f, 0f, -170f };
        public LayoutPoint[] sockets = Array.Empty<LayoutPoint>();
        public LayoutPoint[] dummies = Array.Empty<LayoutPoint>();
        public LayoutTorch[] torchList = Array.Empty<LayoutTorch>();

        public static GrayboxLayout FromJson(string json) => JsonUtility.FromJson<GrayboxLayout>(json);

        public static Vector3 V(float[] a) => a == null || a.Length < 3 ? Vector3.zero : new Vector3(a[0], a[1], a[2]);
    }

    [Serializable]
    public sealed class LayoutBox
    {
        public string name;
        public string kind;
        public float[] p;
        public float[] s;
        public float[] r;
        public bool walkable;
        public bool collide = true;
    }

    [Serializable]
    public sealed class LayoutParapet
    {
        public string name;
        public string axis = "x";
        public float x0, x1, z, z0, z1, y;
        public float thick = 1f;
        public float height;
    }

    [Serializable]
    public sealed class LayoutSpawn
    {
        public float[] p = { 96f, 20.05f, 3f };
        public float yaw = 200f;
    }

    [Serializable]
    public sealed class LayoutPoint
    {
        public string name;
        public float[] p;
    }

    [Serializable]
    public sealed class LayoutTorch
    {
        public float[] p;
    }
}
